<script>export let form;</script><div class="auth card"><p class="eyebrow">Welcome back</p><h1>Log in to OweEasy</h1>{#if form?.error}<p class="error" role="alert">{form.error}</p>{/if}<form method="POST"><label>Email<input name="email" type="email" autocomplete="email" required/></label><label>Password<input name="password" type="password" autocomplete="current-password" required/></label><button class="button">Log in</button></form><div class="todo"><b>Student-owned feature:</b> Google sign-in is intentionally reserved for you. See the TODO in the server action and the implementation plan.</div><p>New here? <a href="/signup">Create an account</a></p></div><style>.auth{margin:4rem auto;max-width:440px}.auth h1{font-size:2.3rem}.auth form{display:grid;gap:1rem;margin:1.5rem 0}.auth p:last-child{color:#58746b}.eyebrow{color:#d26d35;font-weight:800;text-transform:uppercase}.todo{background:#fff8ed;border:1px solid #f1d5a8;border-radius:9px;color:#795526;font-size:.9rem;padding:.75rem}</style>
